package cl.acis.catalogos.model; import jakarta.persistence.*;
@Entity @Table(name="motivos_catalogo") public class MotivoCatalogo { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Enumerated(EnumType.STRING) @Column(nullable=false) TipoMotivo tipo; @Column(nullable=false,length=500) String texto; @Column(nullable=false) boolean activo=true; public MotivoCatalogo(){} public Long getId(){return id;} public TipoMotivo getTipo(){return tipo;} public void setTipo(TipoMotivo v){tipo=v;} public String getTexto(){return texto;} public void setTexto(String v){texto=v;} public boolean isActivo(){return activo;} public void setActivo(boolean v){activo=v;} }
